import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"World-Action Models (WAM)","description":"","frontmatter":{"title":"World-Action Models (WAM)","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/world-action-models.md","filePath":"en/tutorials/world-action-models.md","lastUpdated":null}'),o={name:"en/tutorials/world-action-models.md"};function l(r,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="world-action-models-wam" tabindex="-1">World-Action Models (WAM) <a class="header-anchor" href="#world-action-models-wam" aria-label="Permalink to &quot;World-Action Models (WAM)&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/world-action-models">世界动作模型 WAM</a><strong>Coverage</strong>: June 2025 – August 2026, with foundational work traced back where needed. <strong>Structure</strong>: principles → tasks → data → methods → evaluation → practice → trends. Chapter 9 is the complete grouped paper list.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/world-action-models">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>&quot;World action model&quot; became a fashionable label faster than it became a definition, and Chapter 0 opens by saying so. The tutorial&#39;s response is an <strong>admission contract</strong>: a system is a WAM only if a prediction of the future is <em>load-bearing</em> for the action it emits. Systems that generate a future and then ignore it are world models with a policy bolted on, not WAMs.</p><p>Everything else follows from a four-axis anatomy, introduced in Chapter 2 and used consistently thereafter:</p><ul><li><strong>Action coupling</strong> — how tightly prediction and action are bound (this is the formalisation the tutorial calls the most important in the text).</li><li><strong>Prediction substrate <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Φ</span></span></span></span></strong> — pixels, latents, geometry, or affordances.</li><li><strong>Deployment regime <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span></span></span></span></strong> — the cost model you are actually operating under.</li><li><strong>Training objective family</strong> — what the loss is asking the model to be good at.</li></ul><p>Three method families are then defined by where the prediction stops: <strong>Render-and-Decode</strong> (all the way to pixels), <strong>Latent-Only</strong> (stops at the latent), and <strong>Video-Generation-Free</strong> (no pixel video backbone in the prediction path at all). Chapter 8.1 treats &quot;should we generate pixels?&quot; as the field&#39;s central unresolved tension rather than a settled question.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-what-this-tutorial-is-for" tabindex="-1">Chapter 0 — What this tutorial is for <a class="header-anchor" href="#chapter-0-—-what-this-tutorial-is-for" aria-label="Permalink to &quot;Chapter 0 — What this tutorial is for&quot;">​</a></h3><ul><li>0.1 A term that is getting out of hand</li><li>0.2 Reader paths</li><li>0.3 Scope and conventions</li></ul><h3 id="chapter-1-—-what-a-world-action-model-is" tabindex="-1">Chapter 1 — What a World Action Model is <a class="header-anchor" href="#chapter-1-—-what-a-world-action-model-is" aria-label="Permalink to &quot;Chapter 1 — What a World Action Model is&quot;">​</a></h3><ul><li>1.1 The thirty-second definition</li><li>1.2 Three neighbours that are easily confused with it</li><li>1.3 Why WAM is needed: three failure modes of VLA</li><li>1.4 Where the binding happens decides everything</li><li>1.5 A panorama</li></ul><h3 id="chapter-2-—-mathematical-principles-and-design-space" tabindex="-1">Chapter 2 — Mathematical principles and design space <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-design-space" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and design space&quot;">​</a></h3><ul><li>2.1 A unified formalisation</li><li>2.2 Three kinds of action coupling — the most important formalisation in the tutorial</li><li>2.3 The prediction substrate <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Φ</span></span></span></span>: what should actually be predicted</li><li>2.4 The deployment regime <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span></span></span></span> and its cost model</li><li>2.5 Five competing deployment pressures</li><li>2.6 Families of training objective</li><li>2.7 Action representation and injection interfaces</li><li>2.8 Causal masking: the ten most important lines of code in WAM engineering</li><li>2.9 Error accumulation, on-policy training, and rollout-free methods</li><li>2.10 A table compressing 2.1–2.9 into a decision checklist</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.0 The four roles a WAM can play</li><li>3.1 Robotic manipulation — WAM&#39;s main theatre</li><li>3.2 Autonomous driving — the second-fastest-growing arena</li><li>3.3 Navigation</li><li>3.4 Tasks in the non-control roles</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><ul><li>4.1 The data pyramid, in its WAM-specific form</li><li>4.2 Real-robot manipulation datasets with action labels</li><li>4.3 Human and egocentric video without action labels</li><li>4.4 Simulation, synthesis and neural trajectories</li><li>4.5 Driving data</li><li>4.6 Multi-domain 4D and world-modelling data</li><li>4.7 Pseudo-action quality: the ceiling on any data engine</li></ul><h3 id="chapter-5-—-methods-and-representative-systems" tabindex="-1">Chapter 5 — Methods and representative systems <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems&quot;">​</a></h3><ul><li>5.0 Foundations (†, before 2025.06)</li><li>5.1 Family 1: Render-and-Decode</li><li>5.2 Family 2: Latent-Only</li><li>5.3 Family 3: Video-Generation-Free</li><li>5.4 Choosing among the three families</li><li>5.5 Mechanisms shared across families — the real battleground of 2026</li><li>5.6 Driving WAMs</li><li>5.7 Timeline: key moments from 2025.06 to 2026.08</li><li>5.8 Methods that appear in the survey census but had no section of their own</li></ul><h3 id="chapter-6-—-benchmarks-and-metrics" tabindex="-1">Chapter 6 — Benchmarks and metrics <a class="header-anchor" href="#chapter-6-—-benchmarks-and-metrics" aria-label="Permalink to &quot;Chapter 6 — Benchmarks and metrics&quot;">​</a></h3><ul><li>6.1 The principle in one sentence</li><li>6.2 The five-level evaluation pyramid</li><li>6.3 accuracy-at-budget: the reporting format the survey argues for</li><li>6.4 An overlooked methodology: paired intervention</li><li>6.5 Driving-side evaluation at a glance</li><li>6.6 Using a world model as evaluator, correctly — an operating checklist</li><li>6.7 Three crises in current evaluation, to use as alarms when reading papers</li></ul><h3 id="chapter-7-—-hands-on-building-a-working-wam-from-scratch" tabindex="-1">Chapter 7 — Hands-on: building a working WAM from scratch <a class="header-anchor" href="#chapter-7-—-hands-on-building-a-working-wam-from-scratch" aria-label="Permalink to &quot;Chapter 7 — Hands-on: building a working WAM from scratch&quot;">​</a></h3><ul><li>7.1 Step 0: settle the four coordinates</li><li>7.2 Step 1: choose a base model</li><li>7.3 Step 2: the data recipe</li><li>7.4 Step 3: training essentials</li><li>7.5 Step 4: evaluation, reported per §6.3</li><li>7.6 Step 5: deployment and the right order to optimise in</li><li>7.7 A minimal validation experiment that fits in one week</li></ul><h3 id="chapter-8-—-core-challenges-and-research-trends" tabindex="-1">Chapter 8 — Core challenges and research trends <a class="header-anchor" href="#chapter-8-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 8 — Core challenges and research trends&quot;">​</a></h3><ul><li>8.1 The primary tension: whether to generate pixels at all</li><li>8.2 WAM&#39;s capability boundary relative to VLA — the most important theoretical question</li><li>8.3 The substrate debate: pixels, geometry, or affordances</li><li>8.4 Adaptive computation: dream more or act more</li><li>8.5 Failure, intervention and counterfactual data</li><li>8.6 The evaluation crisis</li><li>8.7 Identity crisis: will the WAM/VLA boundary disappear</li><li>8.8 Questioning whether the four axes are really separable</li><li>8.9 Cross-embodiment and unified large models</li><li>8.10 Safety, robustness and reward hacking</li><li>8.11 Ten concrete open problems you can pick up directly</li></ul><h3 id="chapter-9-—-paper-list-2025-06–2026-08" tabindex="-1">Chapter 9 — Paper list (2025.06–2026.08) <a class="header-anchor" href="#chapter-9-—-paper-list-2025-06–2026-08" aria-label="Permalink to &quot;Chapter 9 — Paper list (2025.06–2026.08)&quot;">​</a></h3><p>Fifteen groups: surveys, positions and theory; foundations; the three families; action representation and interfaces; geometry, physics and 4D; memory, long horizons and agentic outer loops; failure, causality and counterfactuals; adaptive computation, distillation and efficiency; driving WAMs; navigation, humanoids, dexterity and specialist domains; data engines and datasets; RL and post-training inside world models; evaluation and benchmarks.</p><h3 id="appendices" tabindex="-1">Appendices <a class="header-anchor" href="#appendices" aria-label="Permalink to &quot;Appendices&quot;">​</a></h3><ul><li>Appendix A — Terminology cross-reference</li><li>Appendix B — Every base model, benchmark and tool component named in the tutorial, explained and linked: video-generation backbones, simulators and embodiments, manipulation benchmarks ordered by saturation, driving benchmarks, video-quality metrics and tools, representation and algorithm components, the classical RL world-model lineage, early &quot;generation as planning&quot; work, and driving world models whose ids were not verified</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/video-to-wam">From Video Generation to WAM</a> — the same material approached from outside, for video-generation researchers</li><li><a href="/notes/en/tutorials/vla">Vision-Language-Action Models</a> — the family WAM is continually benchmarked against</li><li><a href="/notes/en/tutorials/world-models">World Models</a> — the broader class WAM is a subset of</li></ul>',33)])])}const m=a(o,[["render",l]]);export{u as __pageData,m as default};
